    fr: "Téléchargez l'APK et installez-le directement sur votre appareil Android. Pas besoin de compte Play Store. Sans publicité. Juste des anniversaires.",
    de: "Lade die APK herunter und installiere sie direkt auf deinem Android-Gerät. Kein Play Store-Konto erforderlich. Keine Werbung. Nur Geburtstage.",
    da: "Download APK'en og installer den direkte på din Android-enhed. Ingen Play Store-konto nødvendig. Ingen reklamer. Bare fødselsdage.",
    ja: "APKをダウンロードしてAndroidデバイスに直接インストール。Playストアのアカウント不要。広告なし。誕生日だけ。",
