  install_desc: {
    en: 'To install this APK, enable "Install from unknown sources" in your Android settings. Full source code is publicly viewable on GitHub for anyone to audit: <a href="https://github.com/itszubariel/Track-Birthdays" target="_blank" rel="noopener">view the source code on GitHub</a>.',
    es: 'Para instalar este APK, habilita "Instalar desde fuentes desconocidas" en la configuración de Android. El código fuente completo está disponible públicamente en GitHub para que cualquiera lo audite: <a href="https://github.com/itszubariel/Track-Birthdays" target="_blank" rel="noopener">ver el código fuente en GitHub</a>.',
    fr: 'Pour installer cet APK, activez \u00ab\u00a0Installer des applications inconnues\u00a0\u00bb dans vos paramètres Android. Le code source complet est visible publiquement sur GitHub pour que tout le monde puisse l\'auditer\u00a0: <a href="https://github.com/itszubariel/Track-Birthdays" target="_blank" rel="noopener">voir le code source sur GitHub</a>.',
    de: 'Um diese APK zu installieren, aktiviere \u201eInstallation aus unbekannten Quellen\u201c in deinen Android-Einstellungen. Der vollständige Quellcode ist auf GitHub öffentlich einsehbar, damit jeder ihn prüfen kann: <a href="https://github.com/itszubariel/Track-Birthdays" target="_blank" rel="noopener">Quellcode auf GitHub ansehen</a>.',
    da: 'For at installere denne APK, aktiver \u201eInstaller fra ukendte kilder\u201c i dine Android-indstillinger. Den fulde kildekode er offentligt tilgængelig på GitHub for at alle kan gennemgå den: <a href="https://github.com/itszubariel/Track-Birthdays" target="_blank" rel="noopener">se kildekoden på GitHub</a>.',
    ja: 'このAPKをインストールするには、Android設定で「不明なソースからのインストール」を有効にしてください。ソースコード全体はGitHubで公開されており、誰でも確認できます：<a href="https://github.com/itszubariel/Track-Birthdays" target="_blank" rel="noopener">GitHubでソースコードを見る</a>。',
    ko: '이 APK를 설치하려면 Android 설정에서 \u2018알 수 없는 소스에서 설치\u2019를 활성화하세요. 전체 소스 코드는 누구나 감사할 수 있도록 GitHub에서 공개적으로 볼 수 있습니다: <a href="https://github.com/itszubariel/Track-Birthdays" target="_blank" rel="noopener">GitHub에서 소스 코드 보기</a>.',
    zh: '要安装此APK，请在Android设置中启用「允许安装未知来源的应用」。完整源代码在GitHub上公开供任何人审查：<a href="https://github.com/itszubariel/Track-Birthdays" target="_blank" rel="noopener">在GitHub上查看源代码</a>。',
  },
  download_why_not: {
    en: "<strong>Why not on Play Store?</strong> To keep it 100% free with no ads or tracking. Sideloading gives you complete control.",
    es: "<strong>¿Por qué no está en Play Store?</strong> Para mantenerlo 100% gratuito sin anuncios ni rastreo. La instalación manual te da control total.",
    fr: "<strong>Pourquoi pas sur le Play Store ?</strong> Pour le garder 100% gratuit sans publicité ni suivi. Le chargement latéral vous donne un contrôle total.",
    de: "<strong>Warum nicht im Play Store?</strong> Um es 100% kostenlos ohne Werbung oder Tracking zu halten. Sideloading gibt dir die vollständige Kontrolle.",
    da: "<strong>Hvorfor ikke i Play Store?</strong> For at holde det 100% gratis uden reklamer eller sporing. Sideloading giver dig fuld kontrol.",
    ja: "<strong>なぜPlayストアにないのですか？</strong> 広告やトラッキングなしで完全無料を保つためです。サイドロードにより完全なコントロールが可能です。",
    ko: "<strong>왜 Play Store에 없나요?</strong> 광고나 추적 없이 100% 무료로 유지하기 위해서입니다. 사이드로딩을 통해 완전한 제어권을 가질 수 있습니다.",
    zh: "<strong>为什么不在Play Store上？</strong> 为了保持100%免费，没有广告或追踪。侧载让您拥有完全的控制权。",
  },

