  license_s5_p2: {
    en: 'A full dependency list can be inspected from the project\'s <a href=\\"https://github.com/itszubariel/Track-Birthdays/blob/main/package.json\\">package.json on GitHub</a> or generated with <code>npm ls</code> or a license-checking tool. Archivo Black and Inter are Google Fonts released under the Open Font License.',
    es: 'Una lista completa de dependencias puede ser inspeccionada desde el <a href=\\"https://github.com/itszubariel/Track-Birthdays/blob/main/package.json\\">package.json del proyecto en GitHub</a> o generada con <code>npm ls</code> o una herramienta de verificación de licencias. Archivo Black e Inter son Google Fonts lanzadas bajo la Open Font License.',
    fr: 'Une liste complète des dépendances peut être consultée à partir du <a href=\\"https://github.com/itszubariel/Track-Birthdays/blob/main/package.json\\">package.json du projet sur GitHub</a> ou générée avec <code>npm ls</code> ou un outil de vérification de licence. Archivo Black et Inter sont des polices Google Fonts publiées sous la licence Open Font License.',
    de: 'Eine vollständige Abhängigkeitsliste kann im <a href=\\"https://github.com/itszubariel/Track-Birthdays/blob/main/package.json\\">package.json des Projekts auf GitHub</a> eingesehen oder mit <code>npm ls</code> oder einem Lizenzprüfungstool generiert werden. Archivo Black und Inter sind Google Fonts, die unter der Open Font License veröffentlicht wurden.',
    da: 'En komplet liste over afhængigheder kan ses i projektets <a href=\\"https://github.com/itszubariel/Track-Birthdays/blob/main/package.json\\">package.json på GitHub</a> eller genereres med <code>npm ls</code> eller et licenskontrolværktøj. Archivo Black og Inter er Google Fonts udgivet under Open Font License.',
    ja: '完全な依存関係リストは、GitHub上のプロジェクトの<a href=\\"https://github.com/itszubariel/Track-Birthdays/blob/main/package.json\\">package.json</a>から確認するか、<code>npm ls</code>またはライセンスチェックツールで生成できます。Archivo BlackおよびInterは、Open Font Licenseの下でリリースされたGoogle Fontsです。',
    ko: '전체 의존성 목록은 GitHub의 <a href=\\"https://github.com/itszubariel/Track-Birthdays/blob/main/package.json\\">package.json</a>에서 검사하거나 <code>npm ls</code> 또는 라이선스 확인 도구로 생성할 수 있습니다. Archivo Black과 Inter는 Open Font License에 따라 릴리스된 Google Fonts입니다.',
    zh: '完整的依赖列表可以从 GitHub 上项目的 <a href=\\"https://github.com/itszubariel/Track-Birthdays/blob/main/package.json\\">package.json</a> 中查看，或使用 <code>npm ls</code> 或许可检查工具生成。Archivo Black 和 Inter 是在 Open Font License 下发布的 Google Fonts。',
  },

