  policy_subline: {
    en: "Last updated: July 4, 2026 · Applies to the Track Birthdays web app and Android application.",
    es: "Última actualización: 4 de julio de 2026 · Se aplica a la aplicación web y Android del Rastreador de Cumpleaños.",
    fr: "Dernière mise à jour : 4 juillet 2026 · S'applique à l'application web et Android du Suivi d'Anniversaires.",
    de: "Zuletzt aktualisiert: 4. Juli 2026 · Gilt für die Web-App und Android-Anwendung des Geburtstagstrackers.",
    da: "Sidst opdateret: 4. juli 2026 · Gælder for Fødselsdags-tracker web-appen og Android-applikationen.",
    ja: "最終更新日：2026年7月4日 · 誕生日トラッカーのWebアプリおよびAndroidアプリに適用されます。",
    ko: "최종 업데이트: 2026년 7월 4일 · 생일 트래커 웹 앱 및 Android 애플리케이션에 적용됩니다.",
    zh: "最后更新：2026年7月4日 · 适用于生日追踪网页版和 Android 应用程序。",
  },
  policy_intro: {
    en: 'This Privacy Policy explains how Track Birthdays ("we", "our", or "the app") collects, uses, and protects your information. We keep things simple: your data is used only to make the app work, never for advertising or analytics.',
    es: 'Esta Política de privacidad explica cómo el Rastreador de Cumpleaños ("nosotros", "nuestro" o "la aplicación") recopila, utiliza y protege su información. Mantenemos las cosas simples: sus datos se utilizan solo para que la aplicación funcione, nunca para publicidad o análisis.',
    fr: 'Cette Politique de confidentialité explique comment le Suivi d\'Anniversaires ("nous", "notre" ou "l\'application") collecte, utilise et protège vos informations. Nous faisons simple : vos données sont utilisées uniquement pour faire fonctionner l\'application, jamais pour la publicité ou l\'analyse.',
    de: 'Diese Datenschutzrichtlinie erklärt, wie der Geburtstagstracker ("wir", "unser" oder "die App") Ihre Informationen sammelt, verwendet und schützt. Wir halten die Dinge einfach: Ihre Daten werden nur verwendet, damit die App funktioniert, niemals für Werbung oder Analysen.',
    da: 'Denne privatlivspolitik forklarer, hvordan Fødselsdags-tracker ("vi", "vores" eller "appen") indsamler, bruger og beskytter dine oplysninger. Vi gør tingene enkle: dine data bruges kun til at få appen til at fungere, aldrig til reklame eller analyse.',
    ja: "このプライバシーポリシーは、誕生日トラッカー（「私たち」、「私たちの」、または「アプリ」）がどのように情報を収集、使用、保護するかを説明しています。私たちはシンプルに保っています：あなたのデータはアプリを機能させるためだけに使用され、広告や分析には決して使用されません。",
    ko: '이 개인정보 처리방침은 생일 트래커("우리", "우리의" 또는 "앱")가 귀하의 정보를 어떻게 수집, 사용 및 보호하는지 설명합니다. 우리는 간단하게 유지합니다: 귀하의 데이터는 앱을 작동시키는 데에만 사용되며, 광고나 분석에는 절대 사용되지 않습니다.',
    zh: "本隐私政策解释了生日追踪（“我们”、“我们的”或“该应用程序”）如何收集、使用和保护您的信息。我们保持简单：您的数据仅用于使该应用程序正常工作，绝不用于广告或分析。",
  },
