    en: "You own the data you enter into Track Birthdays. By using the app, you grant us the right to store and process your data solely for the purpose of providing the service. You can export or delete your data at any time from the profile page. We do not claim ownership of your content.",
    es: "Tú eres dueño de los datos que ingresas en el Rastreador de Cumpleaños. Al usar la aplicación, nos otorgas el derecho de almacenar y procesar tus datos únicamente con el fin de proporcionar elservicio. Puedes exportar o eliminar tus datos en cualquier momento desde la página de perfil. No reclamamos la propiedad de tu contenido.",
