    de: "Du besitzt die Daten, die du in den Geburtstagstracker eingibst. Durch die Nutzung der App gewährst du uns das Recht, deine Daten ausschließlich zum Zweck der Bereitstellung des Dienstes zu speichern und zu verarbeiten. Du kannst deine Daten jederzeit von der Profilseite aus exportieren oder löschen. Wir erheben keinen Anspruch auf das Eigentum an deinen Inhalten.",
    da: "Du ejer de data, du indtaster i Fødselsdags-tracker. Ved at bruge appen giver du os ret til at gemme og behandle dine data udelukkende med det formål at levere tjenesten. Du kan til enhver tid eksportere eller slette dine data fra profilsiden. Vi gør ikke krav på ejerskab af dit indhold.",
