    ko: "생일 트래커에 입력한 데이터는 귀하의 소유입니다. 앱을 사용함으로써 귀하는 당사가 서비스를 제공할 목적으로만 데이터를 저장하고 처리할 수 있는 권리를 부여합니다. 프로필 페이지에서 언제든지 데이터를 내보내거나 삭제할 수 있습니다. 당사는 귀하의 콘텐츠에 대한 소유권을 주장하지 않습니다.",
