    ko: "웹 앱은 브라우저(trackbirthdays.netlify.app)에서 실행되며 브라우저의 설치 프롬프트에서 PWA로 설치할 수도 있습니다. APK는 직접 사이드로딩하는 Android 앱입니다. 둘 중 어느 곳에서든 같은 계정으로 로그인하면 모든 것이 동기화됩니다.",
