    es: 'Toca "Ideas de regalos" desde el encabezado de Cumpleaños o un detalle de cumpleaños. Completa los intereses, disgustos, tu relación con la persona y un rango de presupuesto. Groq AI devuelve 6 ideas de regalos personalizadas con una razón para cada una.',
