    ko: '생일 헤더 또는 생일 상세 보기에서 "선물 아이디어"를 누르세요. 관심사, 싫어하는 것, 관계, 예산 범위를 입력하세요. Groq AI가 각각에 대한 이유와 함께 6가지 맞춤형 선물 아이디어를 제공합니다.',
