  help_a20: {
    en: 'Go to Profile and scroll to the Data section. Choose "Export Calendar" for a .ics file that imports into Google Calendar, Apple Calendar, and Outlook, or "Export JSON" for a raw backup of all your birthdays and groups.',
    es: 'Ve a Perfil y desplázate a la sección de Datos. Elige "Exportar calendario" para un archivo .ics que se importa en Google Calendar, Apple Calendar y Outlook, o "Exportar JSON" para una copia de seguridad sin procesar de todos tus cumpleaños y grupos.',
    fr: 'Allez dans Profil et faites défiler jusqu\'à la section Données. Choisissez "Exporter le calendrier" pour un fichier .ics qui s\'importe dans Google Calendar, Apple Calendar et Outlook, ou "Exporter JSON" pour une sauvegarde brute de tous vos anniversaires et groupes.',
    de: "Gehe zu Profil und scrolle zum Bereich Daten. Wähle „Kalender exportieren“ für eine .ics-Datei, die in Google Calendar, Apple Calendar und Outlook importiert werden kann, oder „JSON exportieren“ für eine Rohdatensicherung aller deiner Geburtstage und Gruppen.",
    da: 'Gå til Profil og rul til sektionen Data. Vælg "Eksporter kalender" til en .ics-fil, der kan importeres i Google Kalender, Apple Kalender og Outlook, eller "Eksporter JSON" til en rå backup af alle dine fødselsdage og grupper.',
    ja: "プロファイルに移動し、データセクションまでスクロールします。Googleカレンダー、Appleカレンダー、Outlookにインポートできる.icsファイルには「カレンダーをエクスポート」を、すべての誕生日とグループの生のバックアップには「JSONをエクスポート」を選択してください。",
    ko: '프로필로 이동하여 데이터 섹션으로 스크롤하세요. Google 캘린더, Apple 캘린더, Outlook으로 가져올 수 있는 .ics 파일의 경우 "달력 내보내기"를 선택하거나, 모든 생일 및 그룹의 원본 백업을 위해서는 "JSON 내보내기"를 선택하세요.',
    zh: "前往个人资料并滚动到数据部分。选择“导出日历”以获取可导入 Google 日历、Apple 日历和 Outlook 的 .ics 文件，或选择“导出 JSON”以获取您所有生日和群组的原始备份。",
  },
  help_q21: {
    en: "How do I delete my account?",
    es: "¿Cómo elimino mi cuenta?",
    fr: "Comment supprimer mon compte ?",
    de: "Wie lösche ich mein Konto?",
    da: "Hvordan sletter jeg min konto?",
    ja: "アカウントを削除するには？",
    ko: "계정을 삭제하려면 어떻게 하나요?",
    zh: "如何删除我的账户？",
  },
  help_a21: {
    en: "Go to Profile, Security, Delete Account. You'll be asked to type DELETE to confirm. This permanently removes your account, all birthdays, groups, and photos: there is no way to recover them.",
    es: "Ve a Perfil, Seguridad, Eliminar cuenta. Se te pedirá que escribas DELETE para confirmar. Esto elimina permanentemente tu cuenta, todos los cumpleaños, grupos y fotos: no hay forma de recuperarlos.",
    fr: "Allez dans Profil, Sécurité, Supprimer le compte. Il vous sera demandé de taper DELETE pour confirmer. Cela supprime définitivement votre compte, tous les anniversaires, groupes et photos : il n'y a aucun moyen de les récupérer.",
    de: "Gehe zu Profil, Sicherheit, Konto löschen. Du wirst aufgefordert, DELETE einzugeben, um zu bestätigen. Dies entfernt dein Konto, alle Geburtstage, Gruppen und Fotos dauerhaft: Es gibt keine Möglichkeit, sie wiederherzustellen.",
    da: "Gå til Profil, Sikkerhed, Slet konto. Du bliver bedt om at skrive DELETE for at bekræfte. Dette fjerner permanent din konto, alle fødselsdage, grupper og billeder: der er ingen måde at gendanne dem på.",
    ja: "プロファイル、セキュリティ、アカウント削除の順に進みます。確認のためにDELETEと入力するように求められます。これにより、アカウント、すべての誕生日、グループ、写真が完全に削除され、復元することはできません。",
    ko: "프로필, 보안, 계정 삭제로 이동하세요. 확인을 위해 DELETE를 입력하라는 메시지가 표시됩니다. 그러면 계정, 모든 생일, 그룹 및 사진이 영구적으로 제거되며 복구할 방법이 없습니다.",
    zh: "前往个人资料、安全、删除账户。系统会要求您输入 DELETE 以确认。这将永久删除您的账户、所有生日、群组和照片：无法恢复。",
  },
