    es: 'En la pantalla de inicio de sesión toca "Olvidé mi contraseña", ingresa tu correo electrónico y recibirás un enlace de restablecimiento. También puedes activarlo desde Perfil, Seguridad, Cambiar contraseña si ya has iniciado sesión.',
    fr: 'Sur l\'écran de connexion, appuyez sur "Mot de passe oublié", saisissez votre e-mail et vous recevrez un lien de réinitialisation. Vous pouvez également déclencher cela depuis Profil, Sécurité, Changer le mot de passe si vous êtes déjà connecté.',
    de: "Tippe auf dem Anmeldebildschirm auf „Passwort vergessen“, gib deine E-Mail-Adresse ein und du erhältst einen Link zum Zurücksetzen. Du kannst dies auch unter Profil, Sicherheit, Passwort ändern auslösen, wenn du bereits angemeldet bist.",
    da: 'På loginskærmen skal du trykke på "Glemt adgangskode", indtaste din e-mail, og du vil modtage et link til nulstilling. Du kan også aktivere dette fra Profil, Sikkerhed, Skift adgangskode, hvis du allerede er logget ind.',
    ja: "ログイン画面で「パスワードを忘れた場合」をタップし、メールアドレスを入力するとリセットリンクが届きます。既にサインインしている場合は、プロファイル、セキュリティ、パスワード変更から実行することもできます。",
    ko: '로그인 화면에서 "비밀번호를 잊으셨나요?"를 누르고 이메일을 입력하면 재설정 링크를 받게 됩니다. 이미 로그인한 경우 프로필, 보안, 비밀번호 변경에서도 실행할 수 있습니다.',
    zh: "在登录界面点击“忘记密码”，输入您的电子邮件，您将收到一个重置链接。如果您已经登录，也可以在个人资料、安全、更改密码中触发此操作。",
