  changelog_v1_7_0_item_2_1: {
    en: 'Birthdays: cards have flat ink shadows and lift-on-hover animation, avatar circles have shadows, filter chips have hover and press effects, header redesigned with pill icon buttons; removed the 26-color per-letter system, cards now use monochrome ink with orange accents for the initial letter and "COMING UP" badge; each page has a single accent color (birthdays: orange, add a birthday: lime, gift ideas: blue)',
    es: 'Cumpleaños: las tarjetas tienen sombras de tinta planas y animación de elevación al pasar el mouse, los círculos de avatar tienen sombras, los chips de filtro tienen efectos de pasar el mouse y presionar, el encabezado se rediseñó con botones de icono de píldora; se eliminó el sistema de 26 colores por letra, las tarjetas ahora usan tinta monocromática con acentos naranjas para la letra inicial y la insignia "COMING UP"; cada página tiene un solo color de acento (cumpleaños: naranja, agregar un cumpleaños: lima, ideas de regalo: azul)',
    fr: "Anniversaires : les cartes ont des ombres à l'encre plates et une animation de soulèvement au survol, les cercles d'avatar ont des ombres, les puces de filtre ont des effets de survol et de pression, l'en-tête a été redessiné avec des boutons d'icône en forme de pilule ; le système de 26 couleurs par lettre a été supprimé, les cartes utilisent désormais de l'encre monochrome avec des accents orange pour la lettre initiale et le badge \"COMING UP\" ; chaque page a une seule couleur d'accentuation (anniversaires : orange, ajouter un anniversaire : citron vert, idées de cadeaux : bleu)",
    de: 'Geburtstage: Karten haben flache Tintenschatten und eine Hebe-beim-Hover-Animation, Avatarkreise haben Schatten, Filter-Chips haben Hover- und Presseffekte, Kopfzeile mit pillenförmigen Symbolschaltflächen neu gestaltet; das 26-Farben-pro-Buchstaben-System wurde entfernt, Karten verwenden jetzt monochrome Tinte mit orangefarbenen Akzenten für den Anfangsbuchstaben und das "COMING UP"-Abzeichen; jede Seite hat eine einzige Akzentfarbe (Geburtstage: orange, Geburtstag hinzufügen: limettengrün, Geschenkideen: blau)',
    da: 'Fødselsdage: kort har flade blækskygger og løft-ved-hover-animation, avatar-cirkler har skygger, filter-chips har hover- og tryk-effekter, overskrift redesignet med pille-ikon-knapper; fjernede 26-farver-per-bogstav-systemet, kort bruger nu monokromt blæk med orange accenter for det første bogstav og "COMING UP"-badge; hver side har en enkelt accentfarve (fødselsdage: orange, tilføj fødselsdag: lime, gaveideer: blå)',
    ja: "誕生日：カードにはフラットなインクシャドウとホバー時のリフトアップアニメーションがあり、アバターの円には影があり、フィルターチップにはホバーおよび押下効果があり、ヘッダーはピルアイコンボタンで再設計されました。文字ごとの26色システムは削除され、カードは初期文字と「COMING UP」バッジにオレンジ色のアクセントを付けたモノクロインクを使用するようになりました。各ページには単一のアクセントカラーがあります（誕生日：オレンジ、誕生日を追加：ライム、ギフトアイデア：ブルー）。",
    ko: '생일: 카드는 플랫 잉크 그림자와 호버 시 들어 올리는 애니메이션을 가지고 있고, 아바타 원에는 그림자가 있으며, 필터 칩에는 호버 및 누름 효과가 있고, 헤더는 필 아이콘 버튼으로 재설계되었습니다. 26색 문자 시스템은 제거되었으며 카드는 이제 초기 문자와 "COMING UP" 배지에 주황색 악센트가 있는 단색 잉크를 사용합니다. 각 페이지에는 단일 악센트 색상이 있습니다(생일: 주황색, 생일 추가: 라임, 선물 아이디어: 파란색).',
    zh: "生日：卡片具有扁平墨水阴影和悬停升起动画，头像圆圈有阴影，过滤筹码具有悬停和按压效果，标题重新设计为胶囊图标按钮；移除了每字母 26 色系统，卡片现在使用单色墨水，初始字母和“COMING UP”徽章带有橙色强调色；每个页面都有单一的强调色（生日：橙色，添加生日：青柠色，礼物创意：蓝色）",
  },
